"""Coverage-only registration, followed by past-only matching; no forward/loss calls."""
from common import *
import yaml,bisect,concurrent.futures

def features(values,steps=(250,500,1000)):
 values=np.asarray(values,dtype=np.float64);m=np.abs(values);rms=float(np.sqrt(np.mean(m[-1]**2)))
 if rms<=1e-12:raise ValueError('Degenerate tensor RMS')
 t=np.asarray(steps,dtype=np.float64);t-=t.mean();slope=(t[:,None]*m).sum(0)/float(np.dot(t,t))/rms
 return dict(mag=m[-1],slope=slope,variation=np.abs(np.diff(m,axis=0)).sum(0)/rms,sustained=(m[1]>m[0])&(m[2]>m[1]),rms=rms)

def match(values,key,reg):
 f=features(values);n=values.shape[1];order=np.argsort(f['mag'],kind='stable');small=order[:n//2];pairs=[];candidate_g=0;candidate_s=0
 for stratum,idx in enumerate(np.array_split(small,50)):
  eligible=idx[f['sustained'][idx]];ng=int(math.ceil(len(eligible)*.25));g=eligible[np.lexsort((eligible,-f['slope'][eligible]))[:ng]]
  ns=int(math.ceil(len(idx)*.25));s=idx[np.lexsort((idx,f['variation'][idx]))[:ns]];s=np.setdiff1d(s,g,assume_unique=False);candidate_g+=len(g);candidate_s+=len(s)
  s=s[np.lexsort((s,f['mag'][s]))];avail=s.tolist();mags=f['mag'][s].tolist()
  for gi in g:
   if not avail:break
   j=bisect.bisect_left(mags,float(f['mag'][gi]));choices=[q for q in (j-1,j) if 0<=q<len(avail)];q=min(choices,key=lambda q:(abs(mags[q]-f['mag'][gi]),avail[q]));distance=abs(mags[q]-f['mag'][gi])/f['rms']
   if distance<=reg['matching']['caliper_rms_units']:
    si=avail.pop(q);mags.pop(q);tie=hashlib.sha256(f'77101:{key}:{int(gi)}:{si}'.encode()).hexdigest();pairs.append((float(distance),tie,int(gi),int(si),stratum))
 target=int(round(n*.01));pairs.sort();chosen=pairs[:target];g=np.array([p[2] for p in chosen],dtype=np.int64);s=np.array([p[3] for p in chosen],dtype=np.int64)
 assert len(g)==len(s) and not np.intersect1d(g,s).size and len(np.unique(g))==len(g) and len(np.unique(s))==len(s)
 return g,s,f,dict(target=target,feasible_pairs=len(pairs),growing_candidates=candidate_g,stable_candidates=candidate_s,actual=len(g))

def tensor_job(args):
 seed,name,states,reg=args;values=np.stack([states[st][name].numpy().reshape(-1) for st in (250,500,1000)]);g,s,f,counts=match(values,f'{seed}:{name}',reg);meta=dict(seed=seed,parameter_name=name,layer=int(name.split('.')[1]),expert=int(name.split('.')[4]),tensor=name.split('.')[5]);summary=[];struct=[];k=len(g);dist=np.abs(f['mag'][g]-f['mag'][s])/f['rms'];mg=f['mag'][g];ms=f['mag'][s]
 balance=dict(**meta,pairs=k,dose_fraction=k/values.shape[1],tensor_rms=f['rms'],growing_mean_magnitude=float(mg.mean()) if k else None,stable_mean_magnitude=float(ms.mean()) if k else None,mean_pair_magnitude_mismatch_rms=float(dist.mean()) if k else None,p95_mismatch_rms=float(np.quantile(dist,.95)) if k else None,worst_mismatch_rms=float(dist.max()) if k else None,removed_squared_magnitude_growing=float(np.dot(mg,mg)),removed_squared_magnitude_stable=float(np.dot(ms,ms)),squared_magnitude_relative_difference=float((np.dot(mg,mg)-np.dot(ms,ms))/max(np.dot(ms,ms),1e-30)),standardized_mean_difference=float((mg.mean()-ms.mean())/max(np.sqrt((mg.var()+ms.var())/2),1e-30)) if k else None,**counts)
 examples=[]
 for branch,indices in [('growing',g),('stable',s)]:
  selected_values=values[:,indices];shape=states[1000][name].shape;rows=np.bincount(indices//shape[1],minlength=shape[0]);cols=np.bincount(indices%shape[1],minlength=shape[1])
  struct.append(dict(**meta,branch=branch,count=k,row_occupancy=float(np.mean(rows>0)),column_occupancy=float(np.mean(cols>0)),max_row_share=float(rows.max()/k) if k else None,max_column_share=float(cols.max()/k) if k else None,row_hhi=float(np.sum((rows/max(k,1))**2)),column_hhi=float(np.sum((cols/max(k,1))**2))))
  summary.append(dict(**meta,branch=branch,count=k,mean_slope=float(f['slope'][indices].mean()) if k else None,mean_variation_rms=float(f['variation'][indices].mean()) if k else None,sustained_observed_growth_fraction=float(f['sustained'][indices].mean()) if k else None,mean_abs250=float(np.abs(selected_values[0]).mean()) if k else None,mean_abs500=float(np.abs(selected_values[1]).mean()) if k else None,mean_abs1000=float(np.abs(selected_values[2]).mean()) if k else None,sign_change_fraction=float(np.mean(np.any(np.sign(selected_values[1:])!=np.sign(selected_values[:-1]),axis=0))) if k else None))
  if meta['expert']==0:
   for j in range(min(k,3)):
    index=int(indices[j]);examples.append(dict(**meta,branch=branch,row_major_index=index,row=index//shape[1],column=index%shape[1],signed250=float(values[0,index]),signed500=float(values[1,index]),signed1000=float(values[2,index]),slope=float(f['slope'][index]),variation_rms=float(f['variation'][index]),current_magnitude=float(f['mag'][index])))
 return name,g,s,balance,summary,struct,examples

def main():
 torch.set_num_threads(1);D.mkdir(exist_ok=False);checkpoints={};inventory=[];configs={};old={r['path']:r['sha256'] for r in csv.DictReader((ROOT/'results/expert_exposure_weight_development_v1/inventory.csv').open()) if r['family']=='original_source'}
 for seed in SEEDS:
  checkpoints[str(seed)]={}
  for st in (250,500,1000):
   p=source(seed)/f'checkpoints/step_{st}.pt';h=sha(p);assert h==old[str(p)];cp=torch.load(p,map_location='cpu',weights_only=True,mmap=True);assert cp['step']==st;keys=list(cp);assert 'optimizer' not in cp and 'scaler' not in cp;configs[str(seed)]=cp['config'];mh=state_dict_hash(cp['model'])
   checkpoints[str(seed)][str(st)]=dict(path=str(p),sha256=h,model_hash=mh)
   inventory.append(dict(seed=seed,checkpoint_step=st,path=str(p),sha256=h,model_hash=mh,keys=','.join(keys),optimizer_available=False,scaler_available=False,rng_available=False,family='original unpruned native source'))
 table(D/'checkpoint_inventory.csv',inventory)
 c=configs['17'];assert all(x['model']==c['model'] and x['data']==c['data'] for x in configs.values())
 reg=dict(prospective_intervention=True,motivated_by='expert_exposure_weight_development_v1; overall project not preregistered',source_seeds=list(SEEDS),branch_step=1000,history_steps=[250,500,1000],continuation_attempts=1500,validation_steps=list(EVAL_STEPS),branches=list(BRANCHES),pilot_seed=17,maximum_production_branches=15,checkpoints=checkpoints,source_configs=configs,optimizer_policy='shared fresh AdamW/scaler/RNG reset in ALL branches; source checkpoints omit state',training_precision='canonical FP16 autocast; GradScaler initial65536; TF32 enabled per source configure_device',validation_precision='FP32 TF32 disabled, complete original validation batches; task-only CE token weighted',candidate_definition=dict(population='expert fc1/fc2 weights only; each tensor independently',currently_small='bottom50% ordinal absolute magnitude at1000; ascending flat-index ties',growth='strict increases in |w| at250→500 and500→1000; upper quartile normalized OLS slope among sustained candidates within each of50 current-magnitude rank strata',stability='lower quartile total absolute-magnitude variation across all three observations within each stratum; remove overlap with growth candidates',normalization='OLS slope and trajectory total variation divided by current tensor RMS; never individual magnitude; RMS<=1e-12 is degenerate',quantiles='ceil25% of finite eligible candidates; slope descending/index ascending, variation ascending/index ascending'),matching=dict(strata=50,caliper_rms_units=.005,method='growing candidates in descending slope order per stratum; nearest remaining stable magnitude without replacement; index ties; choose closest feasible pairs first globally per tensor, SHA25677101 tie-break',dose='round(1% of all eligible fc1/fc2 tensor coordinates), equivalent to2% of currently-small population; per-tensor deterministic min(target,feasible_pairs)',reduction='no loss-driven changes; record reduced/zero tensors; abort before loss if any seed removes <0.25% of total expert-weight coordinates or includes <80% of tensors'),primary_endpoint='per-source-seed final task validation CE_growing minus CE_stable at continuation1500',secondary_endpoints=['immediate masking CE minus newly run control','fixed validation curve','trapezoidal integral over registered steps of branch CE minus control CE; also divide integral by1500','applied updates and AMP skips'],success_rule='descriptive paired effects, all5 seeds before mean/median/range/SD/SE; no result-dependent changes or recovered threshold',rng_reset_seeds={str(s):s for s in SEEDS},selection_tie_seed=77101,source_stream='same seeded non-reshuffled loader cycle; reconstruct2500 source batches; continuation uses zero-based slice[1000:2500]',engineering_gate='pilot17 all3 COMPLETE; masks exact, finite weights/loss, expected budget, AMP skips<=100; no use of effect sign',failure_policy='preserve every failed attempt; halt remaining dispatch for numerical failures; no altered protocol or result-based retries; explicit exact resume may reuse interruption state',interruption_interval=250,resource_limits=dict(workers_per_host=1,hosts=list(HOSTS),minimum_gpu_free_gib=24,storage_reserve_gib=40),excluded=['future checkpoints after1000','IMP masks','gradients/validation/final winner status for selection'],mask_files={})
 save(D/'registration.json',reg)
 (D/'protocol.md').write_text('''# Magnitude growth pruning intervention v1\n\nProspective intervention motivated by the retrospective analysis; the overall project was not preregistered. The five compatible original unpruned32E source trajectories are included without performance selection. Branch at1000; past-only history250,500,1000. No future weights or IMP masks enter selection.\n\nCurrent-small is the within-tensor bottom half. Fifty narrow rank strata cover that half. Sustained observed magnitude growth means both observed intervals increase; the top quartile of positive RMS-normalized OLS slopes defines growing candidates. Stable candidates are the bottom quartile of RMS-normalized total trajectory variation, with overlapping growth candidates excluded. Stable-by-net-change fluctuations do not qualify by definition. Exact quantiles, tie handling and matching are in registration.json. No individual-weight denominator is used.\n\nWithin seed/layer/expert/tensor/stratum, greedily match nearest remaining magnitudes within0.005 tensor RMS. Select closest pairs up to round1% of the whole tensor. Reduce per-tensor dose deterministically to feasible pairs. Groups have equal per-tensor counts; record distribution, squared removed magnitude, structure and residual imbalance. Matching does not control connectivity. Seal all five seeds' masks and hashes before validation.\n\nSource optimizer/scaler/RNG states are absent. All branches share a fresh AdamW/scaler/RNG reset and start from the same source1000 state, differing only at selected coordinates. Everything remains trainable; persistent gradient masking and post-update zeroing keep removals zero. Use original canonical LR3e-4, AdamW decay0.01, grad clip1, FP16+GradScaler, auxiliary0.1, learned top1 capacity1.25; no LR scheduler. Use source subsequent batches1001–2500. Newly run reset control is the comparator; historical uninterrupted endpoints are not controls.\n\nComplete, unchanged validation batches and targets; FP32, TF32 disabled, task CE only, actual-token weighting. Evaluate immediately before/after masking and at25,100,250,500,1000,1500 attempted updates. Primary D=CE_growing−CE_stable at1500. Secondary immediate damage, registered curves and trapezoidal excess-CE AUC over0–1500. Report all source-seed effects, then mean, median, range, sample SD and SE; no pseudoreplication or arbitrary recovery threshold. A nonsignificant effect is not equivalence.\n\nPrepare all masks first; engineering pilot seed17 includes all3 branches and remains in the cohort if unchanged. Only numerical/resource integrity gates authorize the other four seeds; effect signs cannot influence dispatch. Maximum15 production branches. One worker per Viper/Adder with locks, heartbeats, unique attempts and atomic statuses. Checkpoints preserve model/optimizer/scaler/all RNG states, logical source offset, metrics and log length; resume restores and truncates only this attempt's uncommitted tail. Failed attempts remain. No additional doses, architectures, branchpoints or algorithms.\n''')
 summaries=[];balances=[];struct=[];examples=[]
 for seed in SEEDS:
  states={st:torch.load(source(seed)/f'checkpoints/step_{st}.pt',map_location='cpu',weights_only=True,mmap=True)['model'] for st in (250,500,1000)};names=sorted(n for n in states[1000] if '.moe.experts.' in n and n.endswith('.weight'));assert len(names)==256;selected_groups={b:{} for b in ('growing','stable')}
  with concurrent.futures.ThreadPoolExecutor(max_workers=4) as pool:
   for name,g,s,balance,summary,st,ex in pool.map(tensor_job,((seed,n,states,reg) for n in names)):
    selected_groups['growing'][name]=torch.from_numpy(g);selected_groups['stable'][name]=torch.from_numpy(s);balances.append(balance);summaries.extend(summary);struct.extend(st);examples.extend(ex)
  removed=sum(len(x) for x in selected_groups['growing'].values());coverage=sum(len(x)>0 for x in selected_groups['growing'].values())/256
  assert removed/67108864>=.0025 and coverage>=.8,'Past-only matching feasibility failed; no interventions authorized'
  p=D/'masks'/f'seed{seed}.pt';atomic_tensor(p,selected_groups);reg['mask_files'][str(seed)]=dict(path=str(p),sha256=sha(p),removed_coordinates_per_branch=removed,achieved_tensor_coverage=coverage,overall_dose=removed/67108864)
  print('matched',seed,'removed',removed,'dose',removed/67108864,flush=True)
  del states
 table(D/'matched_group_summary.csv',summaries);table(D/'magnitude_balance.csv',balances);table(D/'structural_balance.csv',struct);table(D/'coordinate_examples.csv',examples)
 data_identity={}
 for seed in SEEDS:
  train,val=data(seed);data_identity[str(seed)]=dict(full_source_train_hash=R._batch_sequence_hash(train),continuation_train_hash=R._batch_sequence_hash(train[1000:2500]),validation_hash=R._batch_sequence_hash(val),validation_batches=len(val),target_tokens=sum(y.numel() for x,y in val))
  save(D/'data'/f'seed{seed}.json',dict(source_batches=[dict(source_training_step=i+1,batch_hash=R._batch_sequence_hash([b])) for i,b in enumerate(train)],validation_batches=[dict(validation_batch_index=i,batch_hash=R._batch_sequence_hash([b]),shape=list(b[0].shape),target_tokens=b[1].numel()) for i,b in enumerate(val)]));del train,val
 reg['data_identity']=data_identity;reg['data_files']={p:sha(ROOT/p) for p in (c['data']['train_path'],c['data']['validation_path'])};save(D/'registration.json',reg)
 save(D/'preparation_complete.json',dict(status='COMPLETE',no_model_forward_or_loss_calls=True,registration_sha256=sha(D/'registration.json'),mask_matching_code_sha256=sha(HERE/'prepare.py')))
 for seed in SEEDS:
  for b in BRANCHES:save(D/'status'/f'seed{seed}_{b}.json',dict(status='PENDING',seed=seed,branch=b))
